#!/usr/bin/env bash
#Generated by AI with this prompt:
#Mam zlozku tests\translator_test\IFJ26TESTCODES ktora obsahuje ifj26 kody. chcem vytvorit script ktory zoberie obsah celej zlozky a kazdu jednu prezenie cez tests\translator_test\translator_test.c a vysledok ulozi v tests\translator_test\IFJCODE26TEST - nieco na styl - predosle meno_output.ifjcode. ak nastane nejaka chyba tak ju vypise do tests\translator_test\errors.txt ktore budu nejako od seba oddelene. nasledne ked to prelozi a da do folderu tak zoberie ic26int-linux-x86_64 a kazdy jeden ifjcode spusti ic26int-linux-x86_64 meno_kodu. Znova chyby bude davat do skor spomenuteho suboru. niektore budu vyzadovat input. pozri prilozene priklady kodov ktore sa musia prelozit a pre pripad ze vyzaduju input tak tam pridat nieco co ten input da
#tento script by mal byt spustitelny z makefilu
#TODO: override this so its more useful
set -u

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$ROOT_DIR" || exit 1

TRANSLATOR="${TRANSLATOR:-$SCRIPT_DIR/translator_test}"
INTERPRETER="${INTERPRETER:-$SCRIPT_DIR/ic26int-linux-x86_64}"

SRC_DIR="$SCRIPT_DIR/IFJ26TESTCODES"
OUT_DIR="$SCRIPT_DIR/IFJCODE26TEST"
ERR_FILE="$SCRIPT_DIR/errors.txt"

SEP="================================================================"


DEFAULT_INPUT=$'Ahoj svet\n42\n3.5\n'

# ---------------------------------------------------------------- checks
if [[ ! -x "$TRANSLATOR" ]]; then
    echo "Translator not found or not executable: $TRANSLATOR" >&2
    echo "Build it first (make translator-batch does this)." >&2
    exit 1
fi

if [[ ! -f "$INTERPRETER" ]]; then
    echo "Interpreter not found: $INTERPRETER" >&2
    exit 1
fi
[[ -x "$INTERPRETER" ]] || chmod +x "$INTERPRETER"

if [[ ! -d "$SRC_DIR" ]]; then
    echo "Source folder not found: $SRC_DIR" >&2
    exit 1
fi

# ---------------------------------------------------------------- setup
mkdir -p "$OUT_DIR"
: > "$ERR_FILE"

tmp_err="$(mktemp)"
tmp_out="$(mktemp)"
tmp_in="$(mktemp)"
trap 'rm -f "$tmp_err" "$tmp_out" "$tmp_in"' EXIT
printf '%s' "$DEFAULT_INPUT" > "$tmp_in"

# add_error <stage> <file label> <exit code> <file with message>
add_error() {
    {
        echo "$SEP"
        echo "[$1] $2"
        echo "exit code: $3"
        if [[ -s "$4" ]]; then
            cat "$4"
        else
            echo "(no message)"
        fi
        echo
    } >> "$ERR_FILE"
}

n_total=0
n_tr_fail=0
n_run_fail=0
translated=()

# ---------------------------------------------------------------- phase 1: translate
echo "== Translating IFJ26 programs =="
shopt -s nullglob
for src in "$SRC_DIR"/*.ifj26; do
    name="$(basename "$src" .ifj26)"
    out="$OUT_DIR/${name}_output.ifjcode"
    n_total=$((n_total + 1))

    "$TRANSLATOR" "$src" "$out" 2> "$tmp_err"
    rc=$?

    if [[ $rc -ne 0 ]]; then
        n_tr_fail=$((n_tr_fail + 1))
        rm -f "$out"
        add_error "TRANSLATOR" "$name.ifj26" "$rc" "$tmp_err"
        echo "[translate FAIL] $name (exit $rc)"
    else
        translated+=("$name")
        echo "[translate OK]   $name"
    fi
done

# ---------------------------------------------------------------- phase 2: interpret
echo
echo "== Running ic26int on translated programs =="
for name in ${translated[@]+"${translated[@]}"}; do
    code="$OUT_DIR/${name}_output.ifjcode"

    in_file="$SRC_DIR/$name.in"
    [[ -f "$in_file" ]] || in_file="$tmp_in"

    echo
    echo "--- $name"
    # Program output goes to the terminal and to tmp_out (for errors.txt).
    "$INTERPRETER" "$code" < "$in_file" 2>&1 | tee "$tmp_out"
    rc=${PIPESTATUS[0]}

    echo "Exit code: $rc  -----------"

    if [[ $rc -ne 0 ]]; then
        if [[ $rc -eq 40 && $name == *substr* ]]; then
                echo "[expected] $name: runtime error 40 is the intended behavior"
                continue
        fi
        n_run_fail=$((n_run_fail + 1))
        add_error "INTERPRETER" "${name}_output.ifjcode" "$rc" "$tmp_out"
        echo "[run FAIL] $name (exit $rc)"
    fi
done

# ---------------------------------------------------------------- summary
echo
echo "== Summary =="
echo "Programs:             $n_total"
echo "Translator errors:    $n_tr_fail"
echo "Interpreter errors:   $n_run_fail"
echo "Outputs folder:       $OUT_DIR"
echo "Errors file:          $ERR_FILE"

exit 0